'use strict';
const CLASSIC_TABS=[['combat','melee','Combat options'],['skills','skills','Skills'],['quests','quests','Quest list'],['bag','bag','Inventory'],['gear','gear','Worn equipment'],['worship','shrine','Worship'],['spells','spells','Magic'],['friends','friends','Friends list'],['ignore','ignore','Ignore list'],['settings','settings','Settings']];
const classicStorage=document.createElement('div');classicStorage.id='uiStorage';classicStorage.hidden=true;document.body.appendChild(classicStorage);
const classicDockRender=renderPanel,classicSyncTabs=syncTabs,classicOpenSocial=openSocial,classicOpenPanel=openGamePanel;
const classicMobile=()=>window.matchMedia('(pointer: coarse)').matches||window.matchMedia('(max-width: 760px)').matches;
function classicButton(label,action,icon){const b=document.createElement('button');b.type='button';b.title=label;b.setAttribute('aria-label',label);if(icon){b.innerHTML=gameIcon(icon);b.dataset.helpHold='true';}const text=document.createElement('span');text.textContent=label;b.appendChild(text);b.onclick=action;return b;}
function classicHeading(text){const h=document.createElement('h3');h.className='classic-panel-title';h.textContent=text;$('panel').appendChild(h);return h;}
function parkClassicControls(){for(const id of ['combatbar','friendsPane','ambientButton','waveButton','journal','tutorial']){const el=$(id);if(el&&el.parentElement!==classicStorage)classicStorage.appendChild(el);}}
function updateClassicLayout(){document.body.classList.toggle('classic-mobile',classicMobile());document.body.classList.toggle('classic-desktop',!classicMobile());if(typeof resize==='function')resize();}
function updateClassicVitals(){const hp=$('hitpointValue');if(!hp)return;hp.textContent=s.hp;$('hitpointOrb').style.setProperty('--orb-fill',(s.hp/maxhp()*100)+'%');$('hitpointOrb').setAttribute('aria-label','Hitpoints '+s.hp+' of '+maxhp());$('worshipValue').textContent=lv('Worship');$('worshipOrb').setAttribute('aria-label','Worship level '+lv('Worship'));$('coinPouchValue').textContent=s.gold>=1000000?(s.gold/1000000).toFixed(1)+'M':s.gold>=10000?Math.floor(s.gold/1000)+'K':s.gold.toLocaleString();$('coinPouchOrb').setAttribute('aria-label','Coin pouch: '+s.gold.toLocaleString()+' coins. Withdraw coins.');$('coinPouchOrb').title='Coin pouch: '+s.gold.toLocaleString()+' coins';}
function renderClassicCombat(){const p=$('panel'),weapon=equippedWeapon();classicHeading(weapon.name);const level=document.createElement('p');level.className='classic-combat-level';level.textContent='Combat level: '+combatLevel();p.appendChild(level);renderCombatBar();const options=document.createElement('div');options.className='classic-combat-options';for(const option of $('trainingFocus').options){const value=option.value,label=option.textContent.split(' · ')[0],b=classicButton(label,()=>{s[combatStyle()==='melee'?'meleeTraining':combatStyle()+'Training']=value;save();renderClassicPanel();},value==='defensive'?'shield':value==='accurate'||value==='focused'?'accurate':value==='aggressive'?'aggressive':value==='balanced'?'balanced':combatStyle()==='ranged'?'ranged':'magic');b.setAttribute('aria-pressed',String(value===trainingFocus(combatStyle())));b.title=option.textContent;options.appendChild(b);}p.appendChild(options);const resource=document.createElement('p');resource.className='classic-combat-level';resource.textContent=$('combatResource').textContent;p.appendChild(resource);p.appendChild(classicButton('Special attacks',openSpirits,'spirit'));p.appendChild(classicButton('Change equipment',()=>openGamePanel('bag')));}
function renderClassicFriends(ignore=false){const p=$('panel');classicHeading(ignore?'Ignore list':'Friends list');p.appendChild($('friendsPane'));$('friendsPane').hidden=false;renderFriends();$('friendsList').hidden=ignore;$('ignoreList').hidden=!ignore;$('friendForm').querySelector('button[type=submit],button:not([type])').hidden=ignore;$('ignorePlayer').hidden=!ignore;}
function renderClassicWorship(){classicHeading('Worship: '+lv('Worship'));const grid=document.createElement('div');grid.className='classic-spirit-grid';for(const [id,def]of Object.entries(SPIRITS)){const owned=s.spirits?.[id],b=classicButton(def.name,()=>{selectedSpirit=id;openSpirits();},SPIRIT_PANEL_ICONS[id]);b.style.setProperty('--spirit-color',def.color);b.disabled=!owned;b.title=def.name+' — '+(owned?def.bonus+' '+def.ability:def.hint);b.classList.toggle('active',owned?.state==='set');grid.appendChild(b);}const p=document.createElement('p');p.className='desc';p.textContent='Select a bonded spirit to activate it, put it on standby, or unleash its special attack.';$('panel').append(grid,p);}
function renderClassicSettings(){const p=$('panel');classicHeading('Settings');const fullscreen=document.createElement('button');fullscreen.id='fullscreenSettingsButton';fullscreen.type='button';fullscreen.className='classic-setting-button';fullscreen.onclick=togglePlayFullscreen;p.appendChild(fullscreen);for(const id of ['ambientButton','journal']){const b=$(id);for(const label of b.querySelectorAll('.classic-control-label'))label.remove();p.appendChild(b);b.classList.add('classic-setting-button');}syncPlayDisplay();p.appendChild(classicButton('Sound volumes',openSoundSettings,'sound'));p.appendChild(classicButton('Edit appearance',()=>openCreator(true),'appearance'));p.appendChild(classicButton('Icon guide',openIconGuide,'help'));p.appendChild(classicButton('Reset camera',()=>{$('cameraReset').click();},'compass'));p.appendChild(classicButton('Log out',logoutGame,'exit'));}
function renderClassicSpells(){pageControls(1,1);const p=$('panel');p.replaceChildren();classicHeading('Magic: '+lv('Magic'));const grid=document.createElement('div');grid.className='classic-spell-grid';const detail=document.createElement('div');detail.className='classic-spell-detail';detail.setAttribute('role','status');detail.textContent='Select a spell to autocast.';for(const [id,spell]of Object.entries(SPELLS)){const b=document.createElement('button');b.type='button';b.className='classic-spell';b.dataset.spellId=id;b.innerHTML=gameSpellIcon(spell);const label=document.createElement('span');label.className='journal-spell-label';label.textContent=spell.name+' · '+spell.level;b.appendChild(label);b.dataset.helpHold='true';b.style.setProperty('--spell-color',spell.color);b.title=spell.name+' · Magic '+spell.level;b.dataset.tooltip=spell.name+'\nRequires Magic '+spell.level+' · Maximum hit '+spell.power+'\n'+Object.entries(spell.ingredients).map(([r,n])=>n+' '+ITEMS[r].name).join(', ');b.setAttribute('aria-label',b.title);b.setAttribute('aria-pressed',String(s.spell===id));b.classList.toggle('spell-locked',lv('Magic')<spell.level);const describe=()=>{detail.textContent=spell.name+' — Level '+spell.level+'. '+spell.desc+' '+Object.entries(spell.ingredients).map(([id,n])=>n+' '+ITEMS[id].name).join(', ')+'.';};b.onpointerenter=describe;b.onfocus=describe;b.onclick=()=>{describe();if(lv('Magic')<spell.level){toast('You need Magic '+spell.level+' to cast '+spell.name+'.');return;}s.spell=id;if(combatStyle()!=='magic')equipItem('oakStaff');toast(spell.name+' selected for autocasting.');save();renderClassicSpells();};grid.appendChild(b);}p.append(grid,detail);}
function renderClassicPanel(){parkClassicControls();if(tab==='quests')return renderQuestJournal();if(tab==='spells')return renderClassicSpells();const custom=['combat','friends','ignore','settings','worship'].includes(tab);if(!custom){classicDockRender();if(tab==='quests'){const p=$('panel');const extras=document.createElement('div');extras.className='classic-quest-links';extras.appendChild(classicButton('Hunting journal',()=>openGamePanel('hunts'),'hunting'));if(tutorialStep())extras.appendChild(classicButton('Tutorial: '+tutorialStep().title,guide,'tutor'));p.prepend(extras);}return;}
 pageControls(1,1);$('panel').replaceChildren();if(tab==='combat')return renderClassicCombat();if(tab==='friends'||tab==='ignore')return renderClassicFriends(tab==='ignore');if(tab==='worship')return renderClassicWorship();if(tab==='settings')return renderClassicSettings();}
renderPanel=renderClassicPanel;
syncTabs=function(){classicSyncTabs();const title=CLASSIC_TABS.find(t=>t[0]===tab)?.[2];if(title)$('dockTitle').textContent=title;document.body.dataset.panel=tab;};
openGamePanel=function(which,toggle=false){if(['account','emotes','music'].includes(which))which='settings';toolBeltOpen=false;return classicOpenPanel(which,toggle);};
openSocial=function(friends=false){if(friends){openGamePanel('friends');return;}socialRoot.hidden=false;socialUnread=0;chatToggle.classList.remove('unread');$('chatPane').hidden=false;};
function installClassicUi(){document.body.classList.add('classic-ui');parkClassicControls();const tabs=$('gameTabs'),map=$('mapHud');map.appendChild($('spiritButton'));tabs.replaceChildren();for(const [id,icon,title]of CLASSIC_TABS){const b=document.createElement('button');b.type='button';b.dataset.tab=id;setHudButton(b,title,icon);b.setAttribute('aria-controls','gameDock');b.onclick=()=>openGamePanel(id,true);tabs.appendChild(b);}map.appendChild($('runButton'));for(const [id,icon,action]of [['hitpoint','heart',()=>openGamePanel('skills')],['worship','shrine',()=>openGamePanel('worship')],['coinPouch','coins',openCoinPouch]]){const b=document.createElement('button');b.id=id+'Orb';b.type='button';b.className='status-orb';b.innerHTML='<span class="orb-icon">'+gameIcon(icon)+'</span><b id="'+id+'Value"></b>';b.onclick=action;map.appendChild(b);$(id+'Value').dataset.label=({hitpoint:'Health',worship:'Worship',coinPouch:'Coins'})[id];}
 $('spiritButton').onclick=openSpirits;setHudButton('spiritButton','Elemental spirits','followers');socialRoot.setAttribute('aria-label','Game chat');chatToggle.title='Show or hide chat';updateClassicLayout();window.addEventListener('resize',updateClassicLayout);window.visualViewport?.addEventListener('resize',updateClassicLayout);flushGameMessages();}
const classicInitHud=initHud;initHud=function(){classicInitHud();updateClassicLayout();updateClassicVitals();};
installClassicUi();
